CREATE EXTENSION IF NOT EXISTS pgcrypto;
DROP TABLE IF EXISTS audit_logs,notifications,leave_requests,attendance,employees,users CASCADE;
CREATE TABLE users(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),employee_id VARCHAR(40) UNIQUE NOT NULL,email VARCHAR(160) UNIQUE NOT NULL,password_hash TEXT NOT NULL,role VARCHAR(20) NOT NULL CHECK(role IN('EMPLOYEE','HR')),email_verified BOOLEAN DEFAULT FALSE,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE employees(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID UNIQUE NOT NULL REFERENCES users(id) ON DELETE CASCADE,employee_id VARCHAR(40) UNIQUE NOT NULL,name VARCHAR(120) NOT NULL,email VARCHAR(160) NOT NULL,phone VARCHAR(30),address TEXT,profile_picture TEXT,job_title VARCHAR(100),department VARCHAR(100),joining_date DATE,employment_status VARCHAR(30) DEFAULT 'Active',basic_salary NUMERIC(12,2) DEFAULT 0,allowances NUMERIC(12,2) DEFAULT 0,deductions NUMERIC(12,2) DEFAULT 0,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE attendance(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),employee_id UUID NOT NULL REFERENCES employees(id) ON DELETE CASCADE,work_date DATE NOT NULL,check_in TIMESTAMPTZ,check_out TIMESTAMPTZ,working_hours NUMERIC(5,2) DEFAULT 0,status VARCHAR(20) DEFAULT 'Absent' CHECK(status IN('Present','Absent','Half-day','Leave')),UNIQUE(employee_id,work_date));
CREATE TABLE leave_requests(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),employee_id UUID NOT NULL REFERENCES employees(id) ON DELETE CASCADE,leave_type VARCHAR(20) NOT NULL CHECK(leave_type IN('PAID','SICK','UNPAID')),start_date DATE NOT NULL,end_date DATE NOT NULL,remarks TEXT,status VARCHAR(20) DEFAULT 'PENDING' CHECK(status IN('PENDING','APPROVED','REJECTED')),hr_comment TEXT,created_at TIMESTAMPTZ DEFAULT NOW(),updated_at TIMESTAMPTZ DEFAULT NOW(),CHECK(end_date>=start_date));
CREATE TABLE notifications(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,title VARCHAR(160) NOT NULL,message TEXT NOT NULL,type VARCHAR(30) DEFAULT 'INFO',is_read BOOLEAN DEFAULT FALSE,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE TABLE audit_logs(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),user_id UUID REFERENCES users(id),action VARCHAR(100),entity VARCHAR(100),entity_id UUID,details JSONB,created_at TIMESTAMPTZ DEFAULT NOW());
CREATE INDEX idx_attendance_date ON attendance(work_date);CREATE INDEX idx_leave_status ON leave_requests(status);CREATE INDEX idx_notifications_user ON notifications(user_id,is_read);
